let bagPage=0;const BAG_PAGE_SIZE=48;
function sellValue(it){return Math.round((10+it.ilvl*4)*(1+it.rarity*.65)+(it.upgrades||0)*12);}
function sellableItems(){const equipped=new Set(Object.values(player.gear).filter(Boolean)),ids=new Set([...equipped].map(it=>it.id));return player.bag.filter(it=>!it.consumable&&!equipped.has(it)&&!ids.has(it.id));}
function sellAllUnequipped(){const items=sellableItems();if(!items.length)return 0;const sold=new Set(items),gold=items.reduce((sum,it)=>sum+sellValue(it),0);player.bag=player.bag.filter(it=>!sold.has(it));player.gold+=gold;if(sold.has(selected)){selected=null;$('btnEquip').disabled=true;$('btnDrop').disabled=true;showPreview(null);$('dInfo').innerHTML='<div id="dName">Gear sold</div><div id="dType">Equipped gear and health potions are safe.</div>';}bagPage=0;refreshInv();updateObjectives();sound('loot');toast('Sold '+items.length+' items · +'+gold+' gold','#d9b574');saveGame(true);return gold;}
