 for(let i=0;i<3;i++){const it=vendor.stock[i*12].item,proto=itemProto(it,scene),m=inst(proto);m.parent=root;m.position.set(-.43+i*.43,.78,.02);m.scaling.setAll(.48);if(it.slot==='weapon')m.rotation.set(.3,0,Math.PI*.48);}
