function buyVendorItem(index){if(!vendor)return false;const row=vendor.stock[index];if(!row||row.sold||player.gold<row.price)return false;player.gold-=row.price;row.sold=true;player.bag.push(row.item);sound('loot');toast('Purchased '+row.item.name,RARITY[row.item.rarity].c);saveGame(true);refreshInv();if(modalType==='vendor')showVendor();return true;}
