function showVendor(){if(!vendor||!nearStation('vendor'))return;showModal('Sable’s travelling wares','<p>Depth '+G.depth+' · <b>'+player.gold+' gold</b> · '+player.potions+' health potions</p><div class="vendorActions"><button class="prim" id="vendorPotion">Health potion · 30 gold</button><button id="vendorSell">Sell all unequipped · '+sellableItems().reduce((s,it)=>s+sellValue(it),0)+' gold</button></div><div id="vendorGrid">'+vendor.stock.map((row,i)=>'<article class="vendorCard" style="--itemColor:'+RARITY[row.item.rarity].c+'"><div class="vendorRarity">'+RARITY[row.item.rarity].n+' · LV '+row.item.ilvl+'</div><b>'+escaped(row.item.name)+'</b><div class="vendorStat">'+(row.item.slot==='weapon'?Math.round(row.item.baseDmg)+' damage · '+row.item.def.spd.toFixed(2)+'/s':Math.round(row.item.stats.armor)+' armor · +'+Math.round(row.item.stats.hp)+' health')+'</div><div class="vendorStat">'+row.item.affixes.slice(0,3).map(a=>escaped(a.a.fmt(a.v))).join('<br>')+'</div><button data-buy="'+i+'" '+(row.sold||player.gold<row.price?'disabled':'')+'>'+(row.sold?'Sold':row.price+' gold')+'</button></article>').join('')+'</div><p>Stock is unique to this floor. Purchased equipment goes into your satchel. Health potions remain available.</p>','vendor');$('vendorPotion').disabled=player.gold<30;$('vendorPotion').onclick=buyVendorPotion;$('vendorSell').disabled=!sellableItems().length;$('vendorSell').onclick=()=>{sellAllUnequipped();showVendor();};for(const button of $('vendorGrid').querySelectorAll('[data-buy]'))button.onclick=()=>buyVendorItem(Number(button.dataset.buy));}
nearStation=function(which){const p=RUN[which+'Pos'];return p&&Math.hypot(player.pos.x-p.x,player.pos.z-p.z)<(which==='vendor'?2.75:3.4);};
